var POOL_EMPLOYEE = [
 {id:1,c:1,s:0,q:"AI का लागि सबैभन्दा सही पूरा नाम कुन हो?",o:["Automated Internet (स्वचालित इन्टरनेट)","Artificial Intelligence (कृत्रिम बौद्धिकता)","Applied Information (लागू सूचना)","Advanced Integration (उन्नत एकीकरण)"],a:1,e:"AI भनेको Artificial Intelligence हो, जसको नेपाली अर्थ कृत्रिम बौद्धिकता हो।"},
 {id:2,c:1,s:0,q:"LLM भनेको के हो?",o:["ठूलो भाषा मोडल (Large Language Model)","स्थानीय लेखा मोडल (Local Ledger Model)","रेखीय तर्क विधि (Linear Logic Method)","हानिरहित भाषा नक्सा (Lossless Language Map)"],a:0,e:"LLM भनेको Large Language Model हो। यसले ठूलो मात्रामा पाठ अध्ययन गरेर अर्को सम्भाव्य शब्द अनुमान गर्छ।"},
 {id:3,c:1,s:1,q:"नयाँ AI एप डाउनलोड गर्दा पहिले कुन कुरा जाँच्नु सबैभन्दा सुरक्षित हो?",o:["एपको आधिकारिक विकासकर्ता वा प्रकाशक हो कि होइन","एपको आइकनको रङ कस्तो छ","कति जनाले डाउनलोड गरेका छन् भन्ने सङ्ख्या मात्र","एपको नाम कति छोटो छ"],a:0,e:"आधिकारिक प्रकाशक र विश्वसनीय एप स्टोरबाट मात्र डाउनलोड गर्नु सुरक्षित हो।"},
 {id:4,c:1,s:1,q:"खातामा दुई-चरणको प्रमाणीकरण (Two-step verification) सक्रिय गर्नुको मुख्य फाइदा के हो?",o:["पासवर्ड भुल्दा स्वतः नयाँ पासवर्ड बन्ने व्यवस्था","इन्टरनेटको गति बढाउने र डेटा छिटो चल्ने उपाय","एप स्वतः अपडेट हुने र नयाँ सुविधा खुल्ने","पासवर्ड चोरिए पनि दोस्रो चरणबिना खाता खोल्न सकिँदैन"],a:3,e:"दोस्रो चरणले पासवर्ड मात्र चोरिएको अवस्थामा पनि खाताको सुरक्षा कायम राख्छ।"},
 {id:5,c:1,s:2,q:"AI लाई दिइने प्रम्प्ट (Prompt) भनेको के हो?",o:["AI ले बनाएको तयार फोटो","कम्प्युटरको पासवर्ड राख्ने ठाउँ","इन्टरनेट जडान गर्ने उपकरण","AI लाई दिइने निर्देश वा प्रश्न"],a:3,e:"प्रम्प्ट भनेको AI लाई दिइने निर्देश वा प्रश्न हो। यसको गुणस्तरले उत्तरको गुणस्तरमा असर गर्छ।"},
 {id:6,c:1,s:2,q:"प्रम्प्टमा कार्य, सन्दर्भ र चाहिएको ढाँचा स्पष्ट लेख्नुको फाइदा के हो?",o:["उत्तर सधैं लामो र विस्तृत आउँछ","उत्तर अङ्ग्रेजीमा मात्र आउने सम्भावना बढ्छ","AI ले अनुमानको सट्टा सान्दर्भिक उत्तर दिन सक्छ","प्रम्प्ट लेख्न कम समय लाग्छ र सबै काम सकिन्छ"],a:2,e:"स्पष्ट निर्देशले मोडेलले कुन कार्य गर्ने हो र कस्तो उत्तर चाहिएको हो भन्ने बुझ्न मद्दत गर्छ।"},
 {id:7,c:1,s:3,q:"AI ले तयार गरेको पत्र जारी गर्नु अघि अनिवार्य कुन काम हो?",o:["फाइलको नाम र फन्ट मात्र बदलेर त्यसैलाई अन्तिम मान्नु","मूल तथ्य, नाम र अङ्क जाँचेर आवश्यक सम्पादन गर्नु","नागरिकलाई सिधै इमेल गरेर तुरुन्त प्रतिक्रिया लिनु","हस्ताक्षरको ठाउँमा सामान्य पाठ राखेर कागज जारी गर्नु"],a:1,e:"AI ले गलत वा मूल स्रोतमा नभएको विवरण लेख्न सक्छ, त्यसैले जाँच अनिवार्य हो।"},
 {id:8,c:1,s:3,q:"सरकारी पत्रमा AI को सहयोग लिँदा अन्तिम जिम्मेवारी कसको हुन्छ?",o:["AI सेवा प्रदान गर्ने कम्पनीले अन्तिम जिम्मेवारी लिने व्यवस्था","इन्टरनेट सेवा प्रदायकले पत्रको सामग्रीप्रति जिम्मेवार हुने नियम","पत्र हस्ताक्षर गरी जारी गर्ने कर्मचारी वा अधिकारीको","AI मोडेलमा तालिम दिने प्राविधिक टोलीले निर्णय गर्ने प्रक्रिया"],a:2,e:"AI सहायक मात्र हो। निर्णय र हस्ताक्षरको जिम्मेवारी सम्बन्धित अधिकारीको हुन्छ।"},
 {id:9,c:1,s:4,q:"तथ्याङ्कमा समयअनुसार परिवर्तन (प्रवृत्ति) देखाउन कुन चार्ट सबैभन्दा उपयुक्त हुन्छ?",o:["रेखा चार्ट (Line chart)","पाई चार्ट, जसले सबै वर्षलाई एकै क्षणमा देखाउँछ","केवल तालिका, कुनै चित्र नभएको","स्क्याटर बिन्दु, जसमा समय अक्ष हुँदैन"],a:0,e:"रेखा चार्टले समयको क्रममा मानको परिवर्तन स्पष्ट देखाउँछ।"},
 {id:10,c:1,s:5,q:"नागरिकको सेवा अनुरोधको विश्लेषण गर्दा गोपनीयता जोगाउने सबैभन्दा सरल उपाय कुन हो?",o:["सबै विवरण राख्दा मात्र विश्लेषणको नतिजा सटीक र भरपर्दो हुन्छ","नाम, फोन र पहिचान विवरण हटाएर आवश्यक मात्र विवरण राख्नु","AI उपकरणले आफैं गोपनीयता सुनिश्चित गर्ने प्रणाली राखेको हुन्छ","नम्बर र नाम राख्दा AI ले छिटो र राम्रो सिक्ने विश्वास"],a:1,e:"विश्लेषणका लागि अधिकांश समय पहिचानयोग्य विवरण आवश्यक पर्दैन।"},
 {id:11,c:2,s:0,q:"भाषा मोडेलमा 'टोकन' (Token) भनेको के हो?",o:["AI एपको लगइन गर्दा प्रयोग हुने अस्थायी पहिचान कोड","इन्टरनेटमा डेटा पठाउँदा प्रयोग हुने प्याकेटको नाम मात्र","कम्प्युटरको मेमोरीभित्र रहेको डेटाको ठेगाना मात्र","पाठलाई मोडेलले प्रशोधन गर्ने सानो एकाइ (शब्द वा अंश)"],a:3,e:"टोकन भनेको पाठको सानो भाग हो। मोडेलले पाठलाई टोकनमा विभाजन गरेर प्रशोधन गर्छ, र लामो पाठमा धेरै टोकन हुन्छन्।"},
 {id:12,c:2,s:0,q:"AI ले गलत तर विश्वसनीय देखिने जानकारी दिने घटनालाई के भनिन्छ?",o:["Hallucination (काल्पनिक जवाफ)","मोडेल पुरानो भएर अपडेट नहुने अवस्था","फाइल ढाँचा बदलिने समस्या","इन्टरनेट जडानको ढिलाइ"],a:0,e:"Hallucination भनेको मोडेलले तथ्यजस्तो देखिने तर वास्तवमा गलत वा अस्तित्वहीन जानकारी उत्पादन गर्नु हो।"},
 {id:13,c:2,s:0,q:"मेसिन लर्निङ र जेनेरेटिभ AI को सम्बन्ध सबैभन्दा सही कसरी व्याख्या गर्न सकिन्छ?",o:["दुई पूर्ण रूपमा असम्बन्धित प्रणाली हुन् र एउटै सम्बन्ध छैन","मेसिन लर्निङ मात्र नयाँ सामग्री सिर्जना गर्ने प्रणाली हो","दुवै नाम फरक भाषामा एउटै प्रविधिको सङ्केत मात्र हो","जेनेरेटिभ AI, मेसिन लर्निङको शाखा हो जसले नयाँ सामग्री बनाउँछ"],a:3,e:"मेसिन लर्निङ डेटाबाट सिक्ने विधि हो। जेनेरेटिभ AI त्यही विधिको प्रयोगबाट नयाँ सामग्री तयार गर्ने शाखा हो।"},
 {id:14,c:2,s:0,q:"AI मोडेलले सामान्यतया अर्को शब्द कसरी छान्छ?",o:["इन्टरनेटमा खोजेर सत्य तथ्य सिधै कपी गर्ने तरिकाबाट","मानिसले पहिल्यै लेखेको उत्तर खोजेर जस्ताको तस्तै दिने तरिकाबाट","अघिल्ला शब्दको सन्दर्भमा अर्को टोकनको सम्भाव्यता हिसाब गरेर","हरेक शब्दलाई अनियमित रूपमा फेरबदल गर्ने तरिकाबाट"],a:2,e:"भाषा मोडेल सम्भाव्यतामा आधारित हुन्छ। त्यसैले उत्तर सधैं सही हुँदैन, र मानवीय जाँच आवश्यक हुन्छ।"},
 {id:15,c:2,s:1,q:"सार्वजनिक Wi-Fi मा सरकारी कामको संवेदनशील AI खाता खोल्नु उपयुक्त हो कि होइन?",o:["होइन, विश्वसनीय नेटवर्क वा VPN बिना संवेदनशील खाता खोल्न जोखिम हुन्छ","हो, किनभने सार्वजनिक Wi-Fi सधैं सुरक्षित मानिन्छ र कुरा सजिलो हुन्छ","हो, यदि पासवर्ड लामो र जटिल बनाइएको छ भने सुरक्षा पुग्छ","हो, कुनै पनि नेटवर्कमा सुरक्षाको कुनै फरक पर्दैन भन्ने हो"],a:0,e:"सार्वजनिक नेटवर्कमा डेटा अवरोधित हुने जोखिम हुन्छ। विश्वसनीय नेटवर्क वा VPN प्रयोग गर्नु सुरक्षित हुन्छ।"},
 {id:16,c:2,s:1,q:"AI उपकरणबाट 'पासवर्ड भुल्नुभयो' भन्ने इमेल आयो भने सबैभन्दा सुरक्षित कदम कुन हो?",o:["इमेलमा आएको लिङ्कमा तुरुन्त क्लिक गरी नयाँ पासवर्ड सिधै हाल्नु र सक्नु","आधिकारिक एप वा वेबसाइट आफैं खोलेर खाता सेटिङबाट परिवर्तन गर्नु","इमेलको जवाफमा आफ्नो हालको पुरानो पासवर्ड गोप्य रूपमा पठाउनु","सबै सेवाका खाता एउटै पासवर्डमा मिलाएर सजिलो बनाएर राख्नु"],a:1,e:"फिसिङ इमेलले नक्कली लिङ्क दिन सक्छ। आधिकारिक माध्यमबाट सिधै जाँच्नु सुरक्षित हो।"},
 {id:17,c:2,s:1,q:"निःशुल्क AI सेवा प्रयोग गर्दा सेवा प्रदायकको गोपनीयता नीति किन महत्त्वपूर्ण हुन्छ?",o:["डेटा कसरी सङ्कलन, भण्डारण र प्रयोग हुन्छ भन्ने देखाउँछ","सेवाको गति, स्क्रिनको डिजाइन र अपडेटको सूचना मात्र बताउँछ भन्ने","सबै नियम सरकारी कानुनमा अनिवार्य हुने भएकाले मात्र पढ्न पर्ने","नयाँ संस्करण कहिले आउँछ र कति सुविधा थपिन्छ भन्ने सूचना दिन्छ"],a:0,e:"सेवाका सर्त र गोपनीयता नीतिले डेटाको प्रयोगबारे स्पष्ट गर्छ, त्यसैले पढ्नु आवश्यक छ।"},
 {id:18,c:2,s:1,q:"मोबाइलमा AI एप अपडेट गर्दा सुरक्षाको दृष्टिले सबैभन्दा उचित अभ्यास कुन हो?",o:["अज्ञात लिङ्कबाट APK फाइल डाउनलोड गरी इन्स्टल गर्नु","अनुमति नपढी अपडेटको सूचनामा सहमति दिनु","आधिकारिक एप स्टोरबाट मात्र अपडेट लिनु र सुधार जाँच्नु","अपडेट कहिल्यै नगरी पुरानो संस्करण चलाइरहनु"],a:2,e:"अज्ञात स्रोतबाट आएका अपडेट नक्कली हुन सक्छन्। आधिकारिक स्रोत नै सुरक्षित हो।"},
 {id:19,c:2,s:2,q:"प्रम्प्टमा भूमिका दिनुको (जस्तै 'तपाईं नगर प्रशासन अधिकृत हुनुहुन्छ') मुख्य उद्देश्य के हो?",o:["AI लाई इन्टरनेट जडान बन्द गर्न लगाउनु, ताकि उत्तर छिटो आओस्","उत्तरको दृष्टिकोण, शब्दावली र गहिराइ भूमिकाअनुसार मिलाउन","AI को उत्तर स्वचालित रूपमा लामो र बढी शब्दाडम्बरपूर्ण बनाउनु","AI लाई गोप्य सूचना खोजेर ल्याउन लगाउने सीमा हटाउनु"],a:1,e:"भूमिकाले उत्तरको सन्दर्भ र शैली निर्देशित गर्छ, तर यसले तथ्यको शुद्धता स्वतः सुनिश्चित गर्दैन।"},
 {id:20,c:2,s:2,q:"AI को उत्तर अपेक्षित जस्तो नआए सबैभन्दा प्रभावकारी अर्को कदम कुन हो?",o:["उत्तर जस्तो भए पनि स्वीकार गरेर त्यसैलाई अन्तिम मानी अघि बढ्नु","AI उपकरण तुरुन्त पूर्ण रूपमा पुनः स्थापना गरी नयाँ खाता खोल्नु","अर्को विषय छानेर सुरुबाट नयाँ प्रश्न सोधेर पहिलेको काम छोड्नु","के गलत थियो र के चाहियो भनी निर्देश दिएर पुनः प्रम्प्ट पठाउनु"],a:3,e:"स्पष्ट प्रतिक्रिया र थप सीमा दिएर सुधारिएको उत्तर पाउन सकिन्छ।"},
 {id:21,c:2,s:2,q:"प्रम्प्टमा ढाँचा (Format) निर्देश दिँदा के फाइदा हुन्छ?",o:["उत्तर अनिवार्य रूपमा अङ्ग्रेजीमा आउँछ र नेपाली शब्द हराउँछ","उत्तर तालिका, बुँदा वा शीर्षक जस्तो चाहिएको रूपमा आउँछ","उत्तर सधैं एक शब्दमा सीमित भएर विस्तृत विवरण हराउँछ","AI ले प्रम्प्टमा लेखिएका निर्देशहरू पढ्न छाडेर सामान्य उत्तर दिन्छ"],a:1,e:"ढाँचा निर्देशनले उत्तरलाई प्रयोगकर्ताको आवश्यकताअनुसार व्यवस्थित गर्न मद्दत गर्छ।"},
 {id:22,c:2,s:2,q:"एउटै कार्यका लागि दुईवटा प्रम्प्ट तुलना गर्दा राम्रो प्रम्प्ट कसलाई भनिन्छ?",o:["कार्य, सन्दर्भ, श्रोता र अपेक्षित लम्बाइ स्पष्ट लेखिएको","जुन सबैभन्दा छोटो र सरल भाषामा केवल एक वाक्यमा लेखिएको छ","जुन सबैभन्दा लामो र शब्दाडम्बरपूर्ण भाषामा धेरै अनुच्छेदमा लेखिएको छ","जुन अङ्ग्रेजी भाषामा लेखिएको छ र नेपालीमा अनुवाद गरिएको छैन"],a:0,e:"स्पष्ट सन्दर्भ र अपेक्षा भएको प्रम्प्टले सान्दर्भिक र उपयोगी उत्तर दिने सम्भावना बढाउँछ।"},
 {id:23,c:2,s:3,q:"AI ले तयार गरेको मस्यौदा प्रतिवेदन अन्तिम गर्नु अघि सबैभन्दा सतर्क रहनु पर्ने कुरा कुन हो?",o:["मूल स्रोतमा नभएको तथ्य, मिति वा अङ्क थपिएको छ कि छैन जाँच्नु","शीर्षकको फन्ट कस्तो छ र रङ कस्तो छ भन्ने कुरा मात्र हेर्नु पर्छ","पृष्ठ सङ्ख्या र मार्जिन मिलाउनु मात्र पर्याप्त हुन्छ भनी मान्नु","लेखकको नाम र मिति उल्लेख नगर्नु नै सही ढाँचा मानिन्छ"],a:0,e:"AI ले मूल पाठमा नभएको तथ्य थप्न सक्छ, त्यसैले स्रोतसँग मिलाएर जाँच आवश्यक छ।"},
 {id:24,c:2,s:3,q:"अङ्ग्रेजी परिपत्रको नेपाली अनुवाद AI बाट गराएपछि उचित कदम के हो?",o:["अनुवादलाई जस्ताको तस्तै छपाएर छिटो प्रकाशित गर्नु पर्छ","अनुवाद भएको पाठ सिधै नागरिकलाई इमेल गरेर पठाउनु पर्छ","अनुवादको सट्टा मूल अङ्ग्रेजी पाठ मात्र राख्नु सुरक्षित हुन्छ","विषयजानकारले शब्दार्थ र कानुनी अर्थ पुनरावलोकन गरी सच्याउनु"],a:3,e:"अनुवादमा अर्थ फेरिन सक्छ। विषयविज्ञको पुनरावलोकन आवश्यक छ।"},
 {id:25,c:2,s:3,q:"सरकारी पत्रमा AI को सहयोग लिँदा अन्तिम जिम्मेवारी कसको हुन्छ?",o:["AI सेवा प्रदान गर्ने कम्पनीले पत्रको सामग्रीको पूर्ण जिम्मेवारी लिनुपर्छ","इन्टरनेट सेवा प्रदायकले पत्रमा लेखिएको विवरणको जिम्मेवारी लिनुपर्छ","पत्र हस्ताक्षर गरी जारी गर्ने कर्मचारी वा अधिकारीको","AI मोडेललाई तालिम दिने प्राविधिक टोलीले पत्रको अन्तिम निर्णय गर्छ"],a:2,e:"AI सहायक मात्र हो। निर्णय र हस्ताक्षरको जिम्मेवारी सम्बन्धित अधिकारीको हुन्छ।"},
 {id:26,c:2,s:3,q:"अवधारणा-पत्र (Concept Note) को मुख्य उद्देश्य के हो?",o:["कार्यक्रमका फोटो र भिडियो सङ्कलन गरी सामाजिक सञ्जालमा प्रचार गर्नु","कर्मचारीको व्यक्तिगत विवरण सार्वजनिक गरी पारदर्शिता देखाउनु","बजेट खर्चको अन्तिम लेखापरीक्षण गरेर त्यसको रिपोर्ट सार्वजनिक गर्नु","समस्या, औचित्य, उद्देश्य र कार्ययोजना स्पष्ट गरी सहमति सहज बनाउनु"],a:3,e:"अवधारणा-पत्रले विचारलाई संरचित रूपमा प्रस्तुत गर्छ।"},
 {id:27,c:2,s:4,q:"Excel फाइल AI मा अपलोड गर्नु अघि सबैभन्दा महत्त्वपूर्ण तयारी कुन हो?",o:["फाइलको नाम धेरै लामो र अर्थहीन शब्दहरूले भरेर बनाउने","सबै अङ्कलाई रातो रङमा रङ्ग्याएर एउटै पानामा सीमित राख्ने","संवेदनशील स्तम्भ (नाम, ठेगाना, पहिचान नम्बर) हटाउने वा लुकाउने","फाइलका सबै पाना एकै ठाउँमा मर्ज गरेर एउटै तालिका बनाउने"],a:2,e:"व्यक्तिगत तथ्याङ्क सुरक्षित राख्न संवेदनशील स्तम्भ हटाउनु पर्छ।"},
 {id:28,c:2,s:4,q:"AI ले गरेको गणनाको शुद्धता जाँच्ने एउटा सरल तरिका कुन हो?",o:["AI लाई उही प्रश्न फेरि सोधेर उत्तर उस्तै आउँछ कि भनी हेर्नु मात्र","नमूना मानहरू हातैले वा Excel सूत्रबाट पुनः गणना गर्नु","नतिजा ठूलो फन्टमा छापेर सबैलाई देखाएर सहमति लिनु","कुनै गणना नगरी सबै अङ्क नजिकको गोलो सङ्ख्यामा बदल्नु"],a:1,e:"स्वतन्त्र रूपमा पुनः गणना गर्दा त्रुटि पत्ता लाग्छ।"},
 {id:29,c:2,s:4,q:"तथ्याङ्क सफा गर्ने (Data cleaning) क्रममा सबैभन्दा पहिले खोज्नुपर्ने समस्या कुन हो?",o:["दोहोरिएका प्रविष्टि, खाली मान र गलत ढाँचा भएका मान","स्तम्भहरूको रङ फरक भएको छ कि छैन र कुन रङ सुहाउँछ भन्ने","फाइलको आकार ठूलो भएको मात्र हो कि होइन भन्ने कुरा","सबै शीर्षक अङ्ग्रेजीमा भएको छ कि नेपालीमा भन्ने कुरा"],a:0,e:"सफा तथ्याङ्कले विश्लेषणको नतिजा विश्वसनीय बनाउँछ।"},
 {id:30,c:2,s:4,q:"समयअनुसार अङ्कमा भएको परिवर्तन देखाउन कुन चार्ट सबैभन्दा उपयुक्त हुन्छ?",o:["पाई चार्ट, जसले सबै वर्षलाई एकै क्षणमा देखाएर तुलना सजिलो बनाउँछ","केवल तालिका, जसमा कुनै चित्र नभएको र सबै अङ्क मात्र लेखिएको","स्क्याटर बिन्दु, जसमा समय अक्ष नहुने र बिन्दु मात्र देखिने","रेखा चार्ट, जसले समयको क्रममा परिवर्तन स्पष्ट देखाउँछ"],a:3,e:"समय-श्रृङ्खला डेटा (समयको क्रममा मान) का लागि रेखा चार्ट सबैभन्दा सहज हुन्छ।"},
 {id:31,c:2,s:5,q:"नागरिकको सेवा अनुरोध विश्लेषण गर्दा गोपनीयता कसरी जोगाउन सकिन्छ?",o:["सबै विवरण राख्दा मात्र विश्लेषण सटीक र भरपर्दो हुने विश्वास","AI उपकरणले आफैं गोपनीयता सुनिश्चित गर्ने प्रणाली राख्छ भनी मान्नु","नाम, फोन र पहिचान विवरण हटाएर आवश्यक मात्र विवरण राख्नु","नम्बर राख्दा AI छिटो सिक्छ र राम्रो परिणाम दिन्छ भन्ने विश्वास"],a:2,e:"विश्लेषणका लागि अधिकांश समय पहिचानयोग्य विवरण आवश्यक पर्दैन।"},
 {id:32,c:2,s:5,q:"अज्ञात वा शङ्कास्पद इमेल वा लिङ्कमा खाताको पासवर्ड हाल्नु कस्तो हो?",o:["सुरक्षित, किनभने इमेल सरकारी देखिन्छ","सामान्य अभ्यास, यदि लिङ्कको अन्त्यमा .com छ भने","आवश्यक प्रक्रिया, खाता बचाउन","फिसिङ (Phishing) को सम्भावना भएको जोखिमपूर्ण काम"],a:3,e:"पासवर्ड चोर्ने उद्देश्यले नक्कली लिङ्क बनाइएको हुन सक्छ। आधिकारिक स्रोतबाट मात्र लगइन गर्नुपर्छ।"},
 {id:33,c:2,s:5,q:"AI प्रयोग गरी तयार गरिएको सामग्री सार्वजनिक गर्दा नैतिक अभ्यास कुन हो?",o:["AI प्रयोग लुकाएर आफ्नै मौलिक लेखन भनी सार्वजनिक रूपमा प्रस्तुत गर्नु","सामग्रीको स्रोत नखुलाई छिटो प्रकाशित गरेर धेरै पाठक जम्मा गर्नु","AI प्रयोगको उल्लेख गर्नु र तथ्य प्रमाणीकरण गरेर प्रकाशित गर्नु","पाठकको प्रतिक्रिया नलिई प्रकाशित सबै सामग्री चुपचाप मेटाउनु"],a:2,e:"पारदर्शिता र तथ्य प्रमाणीकरण जिम्मेवार प्रयोगका आधार हुन्।"},
 {id:34,c:2,s:5,q:"नयाँ AI सेवा सुरु गर्नु अघि सोध्नुपर्ने सबैभन्दा सान्दर्भिक प्रश्न कुन हो?",o:["सेवाको लोगो कुन रङको छ र त्यो कति आकर्षक देखिन्छ भन्ने कुरा","कसलाई फाइदा, कुन समस्या समाधान, र कसको डेटा कसरी प्रयोग हुन्छ?","सेवाको नाम कति शब्दको छ र सजिलै उच्चारण गर्न सकिन्छ कि भन्ने","सेवा कुन मितिमा अपडेट हुन्छ र कति पटक परिवर्तन हुन्छ भन्ने"],a:1,e:"लाभ, समस्या र डेटा प्रयोगबारे स्पष्ट हुनु सेवा-विचारको मुख्य आधार हो।"},
 {id:35,c:2,s:5,q:"AI सेवा प्रवाहमा नागरिक-केन्द्रित दृष्टिकोणले सबैभन्दा महत्त्वपूर्ण कुन कुरालाई प्राथमिकता दिन्छ?",o:["सबैभन्दा छिटो प्रतिक्रिया मात्र दिने प्रणाली","गोपनीयता, समान पहुँच र मानवीय जवाफदेहिता","सबैभन्दा महँगो प्रविधि किन्ने नीति","कर्मचारीको सङ्ख्या घटाउने लक्ष्य"],a:1,e:"सेवा प्रवाहमा गोपनीयता, समान पहुँच र जवाफदेहिता नै प्राथमिक हुन्।"},
 {id:36,c:3,s:0,q:"एक कर्मचारीले भाषा मोडेललाई 'नेपालको सन् २०२० को बजेटमा सबैभन्दा ठूलो शीर्षक कुन थियो?' भनी सोधे र मोडेलले निश्चित उत्तर दियो। यस परिस्थितिमा सबैभन्दा उपयुक्त निष्कर्ष कुन हो?",o:["मोडेल इन्टरनेटमा जोडिएको छ, त्यसैले उत्तर सधैं सही र अद्यावधिक हुन्छ","निश्चित र आत्मविश्वासपूर्ण उत्तर आउनु नै त्यसको सत्यताको स्पष्ट प्रमाण हो","उत्तर लामो, विस्तृत र व्यवस्थित देखिएकाले त्यसलाई सत्य मान्नु उचित हुन्छ","मोडेलको उत्तर आधिकारिक स्रोतसँग नमिलाई विश्वास गर्नु हुँदैन"],a:3,e:"भाषा मोडेलको आत्मविश्वासपूर्ण उत्तर पनि गलत हुन सक्छ। आधिकारिक बजेट दस्तावेजसँग मिलाउनु पर्छ।"},
 {id:37,c:3,s:0,q:"मोडेलको 'तापक्रम' (temperature) सेटिङ कम गर्दा उत्तरमा सामान्यतया के परिवर्तन आउँछ?",o:["उत्तर सधैं अङ्ग्रेजीमा आउँछ","उत्तर अनियमित र विविध हुन्छ, र तथ्यको शुद्धता स्वतः बढ्छ","उत्तर बढी अनुमानित र स्थिर हुन्छ, र उत्तरको विविधता घट्छ","AI ले इन्टरनेट खोज्न बन्द गर्छ"],a:2,e:"कम तापक्रमले छनोट बढी पूर्वानुमेय बनाउँछ, तर यसले तथ्यको शुद्धता स्वतः सुनिश्चित गर्दैन।"},
 {id:38,c:3,s:0,q:"एउटा मोडेलको तालिम डेटा सन् २०२३ सम्मको छ। सन् २०२६ मा सोधिएको नीतिगत प्रश्नमा सबैभन्दा उचित कदम कुन हो?",o:["मोडेलको उत्तरलाई अन्तिम आधिकारिक निर्णय मानी सिधै नीतिमा लागू गर्नु","मोडेलको पुरानो ज्ञानलाई ताजा तथ्य मानी प्रकाशित गरेर सार्वजनिक गर्नु","हालको आधिकारिक स्रोत जाँचेर उत्तरलाई पुष्टि गर्नु, ज्ञान मितिसम्म सीमित","प्रश्नको उत्तर नपाए कार्य नै रोकेर लामो समयसम्म प्रतीक्षा गर्नु"],a:2,e:"भाषा मोडेलको ज्ञान तालिम डेटाको मितिमा सीमित हुन्छ, त्यसैले ताजा नीतिका लागि स्रोत जाँच आवश्यक छ।"},
 {id:39,c:3,s:0,q:"एक AI सहायकले हरेक पटक एउटै प्रश्नमा फरक उत्तर दिन्छ। यस व्यवहारको सबैभन्दा सम्भावित कारण र उचित व्यवस्थापन कुन हो?",o:["उपकरण खराब भएको स्पष्ट संकेत हो, त्यसैले तुरुन्त बन्द गरेर कुनै काम नगर्नु","उत्तर सम्भाव्यताबाट आउँछ, त्यसैले महत्त्वपूर्ण उत्तर प्रमाणित गर्नु","प्रश्न सधैं ठूलो अक्षरमा लेख्नु पर्ने भन्ने स्पष्ट प्रमाण हो","एउटै उत्तर बारम्बार आउँदा त्यो तुरुन्त सही भएको संकेत मानी स्वीकार्नु"],a:1,e:"एउटै प्रश्नमा फरक उत्तर आउनु सम्भाव्यता-आधारित मोडेलको सामान्य गुण हो। त्यसैले उत्तर प्रमाणित गर्नु आवश्यक छ।"},
 {id:40,c:3,s:1,q:"एउटा कार्यालयको कर्मचारीले मोबाइलमा AI एप डाउनलोड गर्न खोजे। एपको विवरणमा कम्पनीको नाम आधिकारिक वेबसाइटसँग नमिल्दो थियो, र एपले धेरै निःशुल्क सुविधा दिन्छ भनिएको थियो। सबैभन्दा उचित निर्णय कुन हो?",o:["निःशुल्क भएकाले तुरुन्त डाउनलोड गर्नु","सबैले डाउनलोड गरेको भए सुरक्षित हुन्छ भनी मान्नु","नाम मिल्ने आधिकारिक स्रोत पुष्टि नभएसम्म डाउनलोड नगर्नु","पहिले इन्स्टल गरेर पछि सेटिङ हेर्नु"],a:2,e:"नक्कली एपले व्यक्तिगत डेटा चोर्न सक्छ। स्रोत पुष्टि नभई इन्स्टल नगर्नु नै सुरक्षित हो।"},
 {id:41,c:3,s:1,q:"विभिन्न AI सेवामा एउटै पासवर्ड राख्ने कर्मचारीको सबैभन्दा ठूलो जोखिम के हो?",o:["पासवर्ड सबैले सजिलै याद गर्न सक्छन् भने सुरक्षा समस्या हुँदैन","पासवर्ड एकै भएकाले सेवा प्रदायकको सर्भरले छिटो जवाफ दिन्छ","एउटा सेवाको पासवर्ड चुहियो भने अन्य सबै खाता पनि जोखिममा पर्छन्","पासवर्ड लामो र जटिल भएमा मात्र समस्या हुने हुनाले चिन्ता लिनु पर्दैन"],a:2,e:"एउटै पासवर्ड प्रयोग गर्दा एउटा चुहावटले धेरै खातालाई जोखिममा पार्छ।"},
 {id:42,c:3,s:2,q:"एउटा प्रम्प्टमा 'नगरपालिकाको बारेमा लेख' मात्र लेखिएको छ। यसको तुलनामा सबैभन्दा सुधारिएको प्रम्प्ट कुन हो?",o:["नगरपालिकाका सेवा र सुधारबारे सबै कुरा लेख्नुहोस्, कुनै सीमा नराख्नुहोस्।","नगरपालिकाबारे केही राम्रो कुरा लेख्नुहोस्, विवरण आवश्यक छैन।","नागरिक सेवा सुधारका बारेमा बुँदा नराखी केवल संक्षेपमा भन्नुहोस्।","नगर प्रशासन अधिकृतको रूपमा, नागरिक सेवा सुधारका ५ उपाय नेपालीमा बुँदामा दिनुहोस्।"],a:3,e:"भूमिका, विषय, ढाँचा र भाषा स्पष्ट भएको प्रम्प्टले उपयोगी उत्तर दिन्छ।"},
 {id:43,c:3,s:2,q:"AI को उत्तर विस्तृत छ, तर तालिकामा चाहिएको थियो। यस अवस्थामा सबैभन्दा प्रभावकारी प्रम्प्ट संशोधन कुन हो?",o:["अघिल्लो उत्तरलाई विषय, कारण र कार्य स्तम्भको तालिकामा नेपालीमा बदल्नुहोस्।","अघिल्लो उत्तरका सबै शब्दहरू जस्ताको तस्तै पुनः लेखेर पठाउनुहोस्।","उत्तर धेरै छोटो पार्नुहोस्, तर ढाँचाबारे केही पनि नभन्नुहोस्।","नयाँ विषयमा कुनै स्पष्ट निर्देश नदिई फेरि सामान्य प्रश्न सोध्नुहोस्।"],a:0,e:"रूपान्तरणको निर्देशमा स्तम्भ र भाषा तोक्दा अपेक्षित ढाँचा प्राप्त हुन्छ।"},
 {id:44,c:3,s:3,q:"AI ले बनाएको प्रतिवेदनको मस्यौदामा सन् २०२६ को बजेटको अङ्क उल्लेख थियो, तर स्रोत फाइलमा अङ्क फरक थियो। सबैभन्दा उचित कदम कुन हो?",o:["AI ले लेखेको अङ्कलाई नै बढी विश्वसनीय मानी प्रतिवेदनमा राख्नु","स्रोत फाइलको मूल अङ्क राखी फरकको कारण प्रतिवेदनमा लेख्नु","दुवै अङ्क राखी पाठकलाई आफैं छनोट गर्न दिने व्यवस्था मिलाउनु","अङ्क पूरै हटाएर प्रतिवेदन छिटो प्रकाशित गरी काम सकाउनु"],a:1,e:"मूल स्रोतको अङ्क नै आधिकारिक हुन्छ। फरक भएको कारण लेख्नु पारदर्शिता हो।"},
 {id:45,c:3,s:3,q:"एउटा सूचनामा AI ले 'प्रयोगकर्ताले सहमति दिन्छ' भन्ने वाक्य थप्यो, तर नीतिमा त्यस्तो सहमति प्रावधान थिएन। यो किन चिन्ताको विषय हो?",o:["मूल स्रोत नभएको दाबी थपिएको छ, जसले कानुनी र नीतिगत जोखिम ल्याउँछ","वाक्य छोटो र सरल भएकाले पाठकलाई बुझ्न सजिलो हुन्छ भन्ने विचार","AI ले सधैं कानुनसँग मिल्दो र सुरक्षित भाषा प्रयोग गर्ने गर्छ भन्ने","सूचना छोटो भयो भने त्यसको सार्वजनिक मूल्य र विश्वसनीयता बढ्छ भन्ने"],a:0,e:"मूल स्रोतमा नभएको दाबी सार्वजनिक भएमा गलत सूचनाको जोखिम हुन्छ।"},
 {id:46,c:3,s:4,q:"एउटा विभागको मासिक खर्च तथ्याङ्कमा अक्टोबर महिनाको मान अन्यको तुलनामा लगभग दस गुणा ठूलो देखियो। विश्लेषण गर्न सबैभन्दा उचित पहिलो कदम कुन हो?",o:["मानलाई तुरुन्त औसतमा समावेश गरेर अन्तिम नतिजा निकाल्नु र प्रतिवेदन दिनु","ठूलो मानलाई सबैभन्दा सही मानी त्यसकै आधारमा चार्ट र निष्कर्ष बनाउनु","अन्य महिनाका मान हटाएर केवल अक्टोबर महिनाको विश्लेषण मात्र गर्नु","एकाइ, दशमलव वा टाइपोको त्रुटि छ कि छैन, स्रोतसँग मिलाउनु"],a:3,e:"असामान्य मानको कारण पत्ता नलगाई नतिजा निकाल्दा निर्णय गलत हुन सक्छ।"},
 {id:47,c:3,s:4,q:"दुई वर्षको उपस्थिति तथ्याङ्कको प्रस्तुतिमा दर्शक धेरै थिए र तालिका धेरै घना थियो। सबैभन्दा प्रभावकारी सुधार कुन हो?",o:["मुख्य सन्देश रेखा चार्टमा देखाउने र विवरण परिशिष्टमा राख्ने","सबै तालिका ठूलो अक्षरमा रङ्ग्याएर एउटै स्लाइडमा राख्ने","सबै कुरा बोलेर मात्र भन्ने, स्लाइड नराख्ने","तथ्याङ्कको स्रोत हटाएर केवल निष्कर्ष देखाउने"],a:0,e:"एउटा स्लाइडमा एउटा मुख्य सन्देश र विवरण परिशिष्टमा राख्दा श्रोताले सजिलै बुझ्छन्।"},
 {id:48,c:3,s:5,q:"एउटा नगरपालिकाले नागरिकको सेवा रेकर्ड AI सेवामा अपलोड गर्न चाह्यो, तर सेवा प्रदायकको सर्त स्पष्ट छैन र डेटा विदेशी सर्भरमा भण्डारण हुन सक्छ। सबैभन्दा उचित निर्णय कुन हो?",o:["सेवा निःशुल्क भएकाले तुरुन्त सबै रेकर्ड अपलोड गर्नु","स्पष्ट लिखित सर्त नभएसम्म संवेदनशील रेकर्ड अपलोड नगर्नु","नामबाट पहिचान हटाए पर्याप्त हुन्छ भनी अपलोड गर्नु","नागरिकलाई सूचना नदिई गोप्य रूपमा प्रयोग गर्नु"],a:1,e:"सर्त स्पष्ट नभएको सेवामा संवेदनशील डेटा राख्दा नियन्त्रण गुम्न सक्छ।"},
 {id:49,c:3,s:5,q:"एउटा कार्यालयमा AI ले तयार गरेको नागरिक सूचनामा 'प्रमाणित' भनिएको थियो, तर प्रमाणीकरण भएको थिएन। जिम्मेवार प्रकाशनका लागि सबैभन्दा उपयुक्त कदम कुन हो?",o:["'प्रमाणित' शब्द राखी प्रकाशन गर्नु, किनभने सामग्री AI ले बनाएको मात्र हो","प्रमाणीकरण नभएको दाबी हटाउनु, AI प्रयोग उल्लेख गर्नु र पुनरावलोकन गराउनु","AI को नाम मात्र हटाएर बाँकी सामग्री जस्ताको तस्तै सार्वजनिक गर्नु","प्रकाशन भइसकेपछि मात्र गल्ती भए सच्याउने भनी सामग्री अगाडि बढाउनु"],a:1,e:"प्रमाणित नभएको दाबी सार्वजनिक गर्नु गलत हो। पुनरावलोकन र पारदर्शिता आवश्यक छ।"},
 {id:50,c:3,s:5,q:"एउटा सेवा प्रदायकले 'हामी तपाईंको सबै कुराबाट सिक्छौं' भनेर सहमति मागेको छ। सेवाको सर्तमा त्यो सहमति कसरी मूल्याङ्कन गर्नु उचित हुन्छ?",o:["सहमतिको दायरा, अवधि र अस्वीकार गर्ने विकल्प स्पष्ट छ कि छैन जाँचेर","सबै सर्त स्वीकार गरी सेवा तुरुन्त सुरु गरेर छिटो काम सकाउनु","सहमति नदिई सेवा प्रयोग गर्ने वैकल्पिक उपाय मात्र खोजेर बस्नु","सहमति दिइसकेपछि मात्र डेटा कसरी प्रयोग हुन्छ भनी पछि सोध्नु"],a:0,e:"अस्पष्ट सहमतिले डेटा कुन हदसम्म प्रयोग हुन्छ भन्ने थाहा हुँदैन, त्यसैले दायरा जाँच आवश्यक छ।"}
];

/* Pick one event set: 4 simple + 10 medium + 6 complex (same 20:50:30 ratio), random order. */
function pickEventSet(){
  var need = {1:4, 2:10, 3:6}, picked = [];
  [1,2,3].forEach(function(c){
    var ids = POOL_EMPLOYEE.filter(function(q){return q.c===c;}).map(function(q){return q.id;});
    for (var i = ids.length-1; i > 0; i--) { var j = Math.floor(Math.random()*(i+1)); var t = ids[i]; ids[i] = ids[j]; ids[j] = t; }
    picked = picked.concat(ids.slice(0, need[c]));
  });
  for (var k = picked.length-1; k > 0; k--) { var m = Math.floor(Math.random()*(k+1)); var u = picked[k]; picked[k] = picked[m]; picked[m] = u; }
  return picked;
}
